import { defineConfig, loadEnv } from "vite";
import react from "@vitejs/plugin-react-swc";
import path from "path";
import { VitePWA } from 'vite-plugin-pwa';
import fs from 'fs';

// Gera version.json a cada startup/build — garante que /version.json existe em runtime
const version = Date.now().toString();
fs.writeFileSync('./public/version.json', JSON.stringify({ version }));

// https://vitejs.dev/config/
export default defineConfig(({ mode }) => {
  // Carrega TODAS as env vars (prefixo '' = sem filtro VITE_)
  // Necessário para GRAFANA_OTLP_TOKEN estar disponível no proxy
  const env = loadEnv(mode, process.cwd(), '');

  return {
    define: {
      '__APP_VERSION__': JSON.stringify(version),
    },
    server: {
      host: "::",
      port: 8080,
      historyApiFallback: true,
      proxy: {
        '/api/nominatim': {
          target: 'https://nominatim.openstreetmap.org',
          changeOrigin: true,
          rewrite: (path) => path.replace(/^\/api\/nominatim/, ''),
          headers: {
            'User-Agent': 'MommaStockInsight/1.0'
          }
        },
        '/api/otlp': {
          target: 'https://otlp-gateway-prod-sa-east-1.grafana.net',
          changeOrigin: true,
          rewrite: (path) => path.replace(/^\/api\/otlp/, '/otlp'),
          headers: {
            ...(env.GRAFANA_OTLP_TOKEN && {
              Authorization: env.GRAFANA_OTLP_TOKEN,
            }),
          },
        }
      }
    },
    plugins: [
      react(),
      VitePWA({
        // 'prompt' = SW instala mas NÃO recarrega sozinho.
        // O VersionUpdater detecta a nova versão e mostra o banner ao usuário.
        registerType: 'prompt',
        injectRegister: 'auto',
        includeAssets: [
          'logo sistema/favicon.ico',
          'logo sistema/apple-touch-icon.png',
          'logo sistema/android-chrome-192x192.png',
          'logo sistema/android-chrome-512x512.png',
        ],
        manifest: {
          name: 'Momma Stock Insight',
          short_name: 'Momma',
          start_url: '/',
          display: 'standalone',
          theme_color: '#0ea5e9',
          background_color: '#ffffff',
        },
        workbox: {
          // Aumenta limite padrão (2 MiB) para evitar erro de precache em deploy
          maximumFileSizeToCacheInBytes: 15 * 1024 * 1024,
          globPatterns: ['**/*.{js,css,html,ico,png,svg}'],
          navigateFallback: '/index.html',
          navigateFallbackDenylist: [/^\/version\.json/, /^\/api\//],
        },
      }),
    ],
    resolve: {
      alias: {
        "@": path.resolve(__dirname, "./src"),
      },
    },
  };
});

